result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "std_mortality.py", "content": """"Indirect & direct standardization utilities (invented numbers, teaching use).

Reference population age-specific mortality rates are per 1000 person-years.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

Z_95 = 1.959963984540054  # two-sided 95% normal quantile


@dataclass(frozen=True)
class SMRResult:
    observed: float
    expected: float
    smr: float
    ci_lower: float
    ci_upper: float


def _check_bands(labels: list[str], *vectors: list[float]) -> None:
    n = len(labels)
    for v in vectors:
        if len(v) != n:
            raise ValueError(
                f"mismatched band lists: {n} labels vs {len(v)} values"
            )


def expected_deaths(
    ref_rates_per_1000: list[float], person_years: list[float]
) -> float:
    """Indirect method step 1: apply reference rates to cohort person-years."""
    _check_bands([str(i) for i in range(len(ref_rates_per_1000))], person_years)
    if any(py < 0 for py in person_years):
        raise ValueError("person-years must be non-negative")
    return sum((r / 1000.0) * py for r, py in zip(ref_rates_per_1000, person_years))


def byar_ci(observed: float) -> tuple[float, float]:
    """Byar's approximation for the exact Poisson 95% CI of an observed count."""
    if observed < 0:
        raise ValueError("observed count must be non-negative")
    if observed == 0:
        return 0.0, 3.0  # conventional Byar upper limit when obs = 0
    z = Z_95
    lower = observed * (
        1 - 1 / (9 * observed) - z / (3 * math.sqrt(observed))
    ) ** 3
    upper = (observed + 1) * (
        1 - 1 / (9 * (observed + 1)) + z / (3 * math.sqrt(observed + 1))
    ) ** 3
    return lower, upper


def smr(
    observed: float,
    ref_rates_per_1000: list[float],
    person_years: list[float],
) -> SMRResult:
    """Standardized mortality ratio with Byar 95% CI (indirect standardization)."""
    exp = expected_deaths(ref_rates_per_1000, person_years)
    if exp <= 0:
        raise ValueError("expected deaths must be positive")
    ratio = observed / exp
    lo_count, hi_count = byar_ci(observed)
    return SMRResult(observed, exp, ratio, lo_count / exp, hi_count / exp)


def direct_standardized_rate(
    study_deaths_by_band: list[float],
    person_years: list[float],
    standard_population: list[float],
    scale: float = 1000.0,
) -> float:
    """Directly age-standardized rate per `scale` person-years.

    Applies the study cohort's age-specific rates to a standard population's
    age structure (weights proportional to standard_population).
    """
    labels = [str(i) for i in range(len(standard_population))]
    _check_bands(labels, study_deaths_by_band, person_years)
    if any(py <= 0 for py in person_years):
        raise ValueError("person-years must be positive")
    if any(sp < 0 for sp in standard_population) or sum(standard_population) <= 0:
        raise ValueError("standard population must be non-negative and non-empty")
    weights = [sp / sum(standard_population) for sp in standard_population]
    rates = [
        (d / py) * scale for d, py in zip(study_deaths_by_band, person_years)
    ]
    return sum(w * r for w, r in zip(weights, rates))


# ---- Course example (invented numbers) ------------------------------------

REF_RATES = [0.5, 4.0, 20.0, 90.0]          # per 1000 person-years
PERSON_YEARS = [12000.0, 8000.0, 3000.0, 500.0]
OBSERVED_DEATHS = 145.0
# Invented split of the 145 observed deaths by band (for direct standardization):
STUDY_DEATHS_BY_BAND = [8.0, 30.0, 70.0, 37.0]  # sums to 145
# Inline standard population (invented), used only for direct standardization:
STANDARD_POPULATION = [1000.0, 1000.0, 1000.0, 1000.0]


def course_example() -> dict:
    result = smr(OBSERVED_DEATHS, REF_RATES, PERSON_YEARS)
    dsr = direct_standardized_rate(
        STUDY_DEATHS_BY_BAND, PERSON_YEARS, STANDARD_POPULATION
    )
    return {
        "expected": result.expected,
        "smr": result.smr,
        "ci": (result.ci_lower, result.ci_upper),
        "direct_standardized_rate_per_1000": dsr,
    }


if __name__ == "__main__":
    print(course_example())
